    /**
     * Computes (g^n) % p using the exponentiation by squaring algorithm.
     * This method is efficient with a time complexity of O(log n).
     */
    public int modp(int g, int n, int p) {
        long result = 1;
        long base = g % p;
        long exp = n;

        while (exp > 0) {
            // If exp is odd, multiply the base with the result
