import datetime
import requests

class DiaryEntry:
    """
    A class to represent a multilingual diary entry.
    Supported languages: English ('en'), French ('fr'), Spanish ('es').
    """
    SUPPORTED_LANGUAGES = ['en', 'fr', 'es']

    def __init__(self, title, text, mood, weather, lang='en'):
        # Data Validation
        if not all(isinstance(i, str) and len(i.strip()) > 0 for i in [title, text, mood, weather]):
            raise ValueError("Title, text, mood, and weather must be non-empty strings.")
        if lang not in self.SUPPORTED_LANGUAGES:
            raise ValueError(f"Language '{lang}' not supported. Use: {self.SUPPORTED_LANGUAGES}")

        self.title = title
        self.text = text
        self.mood = mood
        self.weather = weather
        self.lang = lang
        self.timestamp = datetime.datetime.now()

    def get_formatted_time(self, hour_format=24):
        """Displays date and time in 12-hour or 24-hour format."""
        if hour_format == 12:
            return self.timestamp.strftime("%Y-%m-%d %I:%M %p")
        elif hour_format == 24:
            return self.timestamp.strftime("%Y-%m-%d %H:%M")
        else:
            raise ValueError("hour_format must be 12 or 24.")

    def analyze_sentiment(self, api_url):
        """
        Analyzes the mood of the diary entry using a provided sentiment analysis API endpoint.
        """
        try:
            payload = {"text": self.text, "language": self.lang}
            response = requests.post(api_url, json=payload, timeout=5)
            response.raise_for_status()
            return response.json().get("sentiment", "Unknown")
        except requests.exceptions.RequestException as e:
            return f"Sentiment analysis service unavailable: {e}"

# Example Usage:
try:
    my_entry = DiaryEntry(
        title="My Day", 
        text="Hoy fue un día maravilloso.", 
        mood="Happy", 
        weather="Sunny", 
        lang="es"
    )
    print(f"Entry Title: {my_entry.title}")
    print(f"Time (12h): {my_entry.get_formatted_time(12)}")
except ValueError as e:
    print(f"Validation Error: {e}")
```

